<?php
require_once __DIR__ . '/../Config/koneksi.php';require_once __DIR__ . '/../Config/auth.php';madin_role_required('admin');require_once __DIR__.'/_layout.php';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){madin_csrf_check();$id=(int)($_POST['id_produk']??0);$qty=(int)($_POST['jumlah']??0);$jenis=(string)($_POST['jenis_mutasi']??'');$ket=trim((string)($_POST['keterangan']??''));if($id<1||$qty<1||!in_array($jenis,['masuk','keluar'],true))$error='Pilih produk dan jumlah stok yang valid.';else{mysqli_begin_transaction($conn);try{$stmt=mysqli_prepare($conn,'SELECT stok FROM produk WHERE id_produk=? FOR UPDATE');mysqli_stmt_bind_param($stmt,'i',$id);mysqli_stmt_execute($stmt);$p=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));mysqli_stmt_close($stmt);if(!$p)throw new RuntimeException('Produk tidak ditemukan.');$before=(int)$p['stok'];$after=$jenis==='masuk'?$before+$qty:$before-$qty;if($after<0)throw new RuntimeException('Stok tidak cukup untuk dikurangi.');$status=$after===0?'habis':'tersedia';$stmt=mysqli_prepare($conn,'UPDATE produk SET stok=?,status_produk=IF(status_produk="nonaktif","nonaktif",?) WHERE id_produk=?');mysqli_stmt_bind_param($stmt,'isi',$after,$status,$id);if(!mysqli_stmt_execute($stmt))throw new RuntimeException(mysqli_stmt_error($stmt));mysqli_stmt_close($stmt);$stmt=mysqli_prepare($conn,'INSERT INTO mutasi_stok(id_produk,jenis_mutasi,jumlah,stok_sebelum,stok_sesudah,keterangan) VALUES(?,?,?,?,?,?)');mysqli_stmt_bind_param($stmt,'isiiis',$id,$jenis,$qty,$before,$after,$ket);if(!mysqli_stmt_execute($stmt))throw new RuntimeException(mysqli_stmt_error($stmt));mysqli_stmt_close($stmt);mysqli_commit($conn);header('Location: stok.php?msg='.rawurlencode('Mutasi stok berhasil disimpan.'));exit;}catch(Throwable $e){mysqli_rollback($conn);$error=$e->getMessage();}}}
$products=mysqli_query($conn,"SELECT id_produk,nama_produk,stok,harga,status_produk FROM produk WHERE status_produk<>'nonaktif' ORDER BY nama_produk");$history=mysqli_query($conn,'SELECT m.*,p.nama_produk FROM mutasi_stok m JOIN produk p ON p.id_produk=m.id_produk ORDER BY m.dibuat_pada DESC LIMIT 30');madin_admin_header('Manajemen Stok','stok');if($error):?><div class="notice error"><?=madin_e($error)?></div><?php endif;?>
<div class="admin-card"><h2>Penyesuaian stok</h2><form class="admin-form" method="post"><input type="hidden" name="csrf_token" value="<?=madin_e(madin_csrf_token())?>"><div class="field full"><label>Produk</label><select name="id_produk" required><option value="">Pilih produk</option><?php if($products):while($p=mysqli_fetch_assoc($products)):?><option value="<?=$p['id_produk']?>"><?=madin_e($p['nama_produk'])?> — stok saat ini: <?=$p['stok']?></option><?php endwhile;endif;?></select></div><div class="field"><label>Jenis mutasi</label><select name="jenis_mutasi"><option value="masuk">Stok masuk</option><option value="keluar">Stok keluar</option></select></div><div class="field"><label>Jumlah</label><input type="number" min="1" name="jumlah" required></div><div class="field full"><label>Keterangan</label><input name="keterangan" maxlength="255" placeholder="Contoh: pembelian bahan atau stok rusak"></div><div class="form-actions"><button class="btn">Simpan mutasi</button></div></form></div>
<div class="admin-card"><h2>Riwayat mutasi stok terbaru</h2><table class="admin-table"><thead><tr><th>Tanggal</th><th>Produk</th><th>Jenis</th><th>Jumlah</th><th>Sebelum</th><th>Sesudah</th><th>Keterangan</th></tr></thead><tbody><?php if($history&&mysqli_num_rows($history)):while($m=mysqli_fetch_assoc($history)):?><tr><td><?=madin_e(date('d/m/Y H:i',strtotime($m['dibuat_pada'])))?></td><td><?=madin_e($m['nama_produk'])?></td><td><?=madin_e(madin_status_label($m['jenis_mutasi']))?></td><td><?=$m['jumlah']?></td><td><?=$m['stok_sebelum']?></td><td><?=$m['stok_sesudah']?></td><td><?=madin_e($m['keterangan']??'—')?></td></tr><?php endwhile;else:?><tr><td colspan="7" class="empty-state">Belum ada riwayat mutasi.</td></tr><?php endif;?></tbody></table></div><?php madin_admin_footer(); ?>
